jest.mock('react-native', () => ({ Platform: { OS: 'android' } }));
jest.mock('../NativeBugsee', () => require('../__mocks__/native').nativeMock);

import * as pkg from '../index';
import Bugsee from '../index';
import api from '../../../../scripts/sdk-api.json';
import nativeVersions from '../../../../native-versions.json';
import { ANDROID, IOS, type Mapping } from '../../../../scripts/sdk-api-map';
import { parseAndroidApi, parseIosApi } from '../../../../scripts/sdk-api';

/**
 * The public methods of the pinned native SDKs (`sdk-api.json`, regenerated by
 * `cli-extract-sdk-api.ts`) against where this package exposes each one.
 *
 * Fails in three directions: an SDK method with no entry (a new method nobody
 * has decided about), an entry naming nothing in the SDK (stale), and an entry
 * pointing at an RN member that does not exist (a mapping that lies).
 */
const platforms = [
  ['android', api.android, ANDROID],
  ['ios', api.ios, IOS],
] as const;

describe('the snapshot describes the pinned SDKs', () => {
  it('was extracted at the versions in native-versions.json', () => {
    // A native-versions bump fails here until `cli-extract-sdk-api.ts` is re-run against the new
    // release, which is when a method the release added gets its mapping or exemption.
    expect(api.sdk).toEqual({
      android: nativeVersions.android.sdk,
      ios: nativeVersions.ios.sdk,
    });
  });
});

describe.each(platforms)('%s SDK API parity', (_platform, methods, map) => {
  const names = methods.map((m) => m.name);

  it('maps or exempts every public SDK method', () => {
    expect(names.filter((name) => !(name in map))).toEqual([]);
  });

  it('has no entry for a method the SDK does not have', () => {
    expect(Object.keys(map).filter((name) => !names.includes(name))).toEqual([]);
  });

  it('points every mapping at a member that exists', () => {
    const broken = Object.entries(map as Record<string, Mapping>).filter(([, mapping]) => {
      if ('rn' in mapping) {
        return !(mapping.rn in (Bugsee as unknown as Record<string, unknown>));
      }
      if ('export' in mapping) {
        return !(mapping.export in pkg);
      }
      return false;
    });
    expect(broken.map(([name]) => name)).toEqual([]);
  });

  it('gives every exemption a reason', () => {
    for (const mapping of Object.values(map as Record<string, Mapping>)) {
      if ('skip' in mapping) {
        expect(mapping.skip.length).toBeGreaterThan(10);
      }
    }
  });
});

describe('the extractors', () => {
  it('read overloads once and flag a deprecated name only when every overload is', () => {
    const source = `
      public final class Bugsee {
        @Deprecated
        public static void old(int a) {}
        public static void old(String a) {}
        @Deprecated
        public static void gone() {}
        public static <T extends Extension> T ext(Class<T> type) { return null; }
        private static void hidden() {}
      }`;
    expect(parseAndroidApi(source)).toEqual([
      { name: 'ext', deprecated: false },
      { name: 'gone', deprecated: true },
      { name: 'old', deprecated: false },
    ]);
  });

  it('read a declaration split across lines, which a line-by-line reading missed', () => {
    const source = `
      public final class Bugsee {
        public static void single() {}
        public static
            void modifiersSplit() {}
        public static void
            nameOnNextLine() {}
        public static <T extends Extension>
            T genericSplit(Class<T> type) { return null; }
        @Deprecated
        public static
            void deprecatedSplit() {}
        public static final int FIELD = compute(1);
        public static class Nested {
          void notAMethod() {}
        }
        // public static void inAComment() {}
        /* public static void inABlockComment() {} */
      }`;
    expect(parseAndroidApi(source)).toEqual([
      { name: 'deprecatedSplit', deprecated: true },
      { name: 'genericSplit', deprecated: false },
      { name: 'modifiersSplit', deprecated: false },
      { name: 'nameOnNextLine', deprecated: false },
      { name: 'single', deprecated: false },
    ]);
  });

  it('read the class methods and properties of the iOS Bugsee interface only', () => {
    const header = `
      @interface Other : NSObject
      + (void)notMine;
      @end
      @interface Bugsee : NSObject
      @property (nonatomic, weak) id delegate;
      + (void)launchWithToken:(NSString *)token;
      + (nullable id)ext:(Class)type;
      - (void)instanceOnly;
      @end`;
    expect(parseIosApi(header).map((m) => m.name)).toEqual(['delegate', 'ext', 'launchWithToken']);
  });

  it('refuse a source that holds nothing, rather than reporting an empty API', () => {
    expect(() => parseAndroidApi('class X {}')).toThrow();
    expect(() => parseIosApi('@interface Bugsee : NSObject\n@end')).toThrow();
    expect(() => parseIosApi('nothing')).toThrow();
  });
});
